import React, { useEffect, useRef, useState } from "react";
import { collection, getDocs, doc, updateDoc, deleteDoc, query, where } from "firebase/firestore";
import { db } from "../firebase";
import { useAuth } from "../context/AuthContext";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import staticMembers from "../data/members.json";
import "./AdminPage.css";

export default function AdminPage() {
  const { currentUser, isAdmin, loading } = useAuth();
  const navigate = useNavigate();

  const [users, setUsers] = useState([]);
  const [members, setMembers] = useState([]);
  const [saving, setSaving] = useState(null);
  const [fetching, setFetching] = useState(true);
  const [exporting, setExporting] = useState(false);
  const fileHandleRef = useRef(null);

  useEffect(() => {
    if (!loading && (!currentUser || !isAdmin)) navigate("/");
  }, [loading, currentUser, isAdmin, navigate]);

  useEffect(() => {
    if (!isAdmin) return;
    async function load() {
      // members 목록
      const memberSnap = await getDocs(collection(db, "members"));
      const memberList = memberSnap.empty
        ? staticMembers
        : memberSnap.docs.map((d) => ({ ...d.data(), id: d.id }));
      memberList.sort((a, b) => Number(a.id) - Number(b.id));
      setMembers(memberList);

      // users 목록
      const userSnap = await getDocs(collection(db, "users"));
      const userList = userSnap.docs.map((d) => {
        const data = { uid: d.id, ...d.data() };
        // 이메일 자동 매칭
        if (data.memberId == null) {
          const matched = memberList.find(
            (m) => (m.links?.email || "").toLowerCase() === (data.email || "").toLowerCase()
          );
          data._suggested = matched ? matched.id : null;
          data._suggestedName = matched ? matched.name : null;
        }
        return data;
      });
      setUsers(userList);
      setFetching(false);
    }
    load();
  }, [isAdmin]);

  const toggleNetworking = async (uid, current) => {
    setSaving(uid + "_net");
    await updateDoc(doc(db, "users", uid), { networkingEditor: !current });
    setUsers((prev) =>
      prev.map((u) => u.uid === uid ? { ...u, networkingEditor: !current } : u)
    );
    setSaving(null);
  };

  const approve = async (uid, memberId) => {
    if (!memberId && memberId !== 0) return;
    setSaving(uid);
    await updateDoc(doc(db, "users", uid), { memberId: Number(memberId) });
    setUsers((prev) =>
      prev.map((u) => u.uid === uid ? { ...u, memberId: Number(memberId) } : u)
    );
    setSaving(null);
  };

  const revoke = async (uid) => {
    setSaving(uid + "_revoke");
    await updateDoc(doc(db, "users", uid), { memberId: null });
    setUsers((prev) =>
      prev.map((u) => u.uid === uid ? { ...u, memberId: null, _suggested: u.memberId, _suggestedName: members.find(m => String(m.id) === String(u.memberId))?.name ?? null } : u)
    );
    setSaving(null);
  };

  const CSV_SHEET_URL = "https://docs.google.com/spreadsheets/d/1yAeYVbqyFwePzjjdU0ile_OAmZ-cR8iwu_95KPVsx7o/export?format=csv&gid=0";

  const fmtDate = (ts) => {
    if (!ts) return "";
    const d = ts.toDate ? ts.toDate() : new Date(ts.seconds * 1000);
    return `${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,"0")}.${String(d.getDate()).padStart(2,"0")}`;
  };

  const esc = (v) => {
    const s = String(v ?? "");
    return s.includes(",") || s.includes('"') || s.includes("\n") ? `"${s.replace(/"/g,'""')}"` : s;
  };

  const exportCSV = async (statusFilter) => {
    setExporting(true);
    try {
      // 1. 기존 구글시트 CSV 가져오기
      let existingLines = [];
      try {
        const res = await fetch(CSV_SHEET_URL);
        const text = await res.text();
        const lines = text.replace(/\r/g, "").split("\n").filter((l) => l.trim());
        existingLines = lines.slice(1); // 헤더 제외
      } catch {
        // 실패 시 빈 상태로 진행
      }

      // 기존 (이름||계획번호) 키 세트 — 중복 방지
      const existingKeys = new Set();
      existingLines.forEach((line) => {
        const cols = line.split(",");
        const name = (cols[1] ?? "").replace(/^"|"$/g, "").trim();
        const num  = (cols[2] ?? "").replace(/^"|"$/g, "").trim();
        if (name && num) existingKeys.add(`${name}||${num}`);
      });

      // 2. Firestore에서 계획 가져오기
      const q = statusFilter
        ? query(collection(db, "livePlans"), where("status", "==", statusFilter))
        : collection(db, "livePlans");
      const snap = await getDocs(q);

      // 3. 기존에 없는 것만 추가
      const newRows = [];
      snap.docs.forEach((d) => {
        const p = d.data();
        const key = `${p.authorName ?? ""}||${p.planNumber ?? ""}`;
        if (!existingKeys.has(key)) {
          newRows.push([
            existingLines.length + newRows.length + 1,
            esc(p.authorName),
            p.planNumber ?? "",
            esc(p.content),
            p.status === "done" ? "완료" : "미완료",
            fmtDate(p.createdAt),
            fmtDate(p.completedAt),
          ].join(","));
        }
      });

      // 4. 합치기
      const header = "ID,이름,계획번호,계획내용,상태,생성일,완료일";
      const allLines = [...existingLines, ...newRows];
      const csv = "﻿" + [header, ...allLines].join("\n");
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });

      // File System Access API — 고정 파일에 덮어쓰기
      if ("showSaveFilePicker" in window) {
        try {
          if (!fileHandleRef.current) {
            fileHandleRef.current = await window.showSaveFilePicker({
              suggestedName: "kora-plans.csv",
              types: [{ description: "CSV", accept: { "text/csv": [".csv"] } }],
            });
          }
          const writable = await fileHandleRef.current.createWritable();
          await writable.write(blob);
          await writable.close();
          alert(`저장 완료 — 기존 ${existingLines.length}행 + 신규 ${newRows.length}행 = 총 ${allLines.length}행`);
          return;
        } catch (err) {
          if (err.name === "AbortError") return;
          fileHandleRef.current = null;
        }
      }

      // 폴백: 일반 다운로드
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "kora-plans.csv";
      a.click();
      URL.revokeObjectURL(url);
    } finally {
      setExporting(false);
    }
  };

  const resetFileHandle = () => {
    fileHandleRef.current = null;
    alert("다음 저장 시 파일 위치를 다시 선택할 수 있어요.");
  };

  const [deduping, setDeduping] = useState(false);
  const deduplicatePlans = async () => {
    if (!window.confirm("Firebase에서 중복 계획(이름+번호 동일)을 제거할까요? 최신 문서만 남기고 나머지는 삭제돼요.")) return;
    setDeduping(true);
    try {
      const snap = await getDocs(collection(db, "livePlans"));
      const map = new Map();
      snap.docs.forEach((d) => {
        const p = d.data();
        const key = `${p.authorName ?? ""}||${p.planNumber ?? ""}`;
        if (!map.has(key)) {
          map.set(key, []);
        }
        map.get(key).push({ id: d.id, createdAt: p.createdAt?.seconds ?? 0 });
      });

      const toDelete = [];
      map.forEach((docs) => {
        if (docs.length <= 1) return;
        // 가장 최신 것(createdAt 높은 것) 하나만 남김
        docs.sort((a, b) => b.createdAt - a.createdAt);
        toDelete.push(...docs.slice(1).map((d) => d.id));
      });

      for (const id of toDelete) {
        await deleteDoc(doc(db, "livePlans", id));
      }
      alert(`완료: ${toDelete.length}개 중복 문서 삭제됨`);
    } finally {
      setDeduping(false);
    }
  };

  if (loading || fetching) {
    return <div style={{ color: "#fff", padding: 40, textAlign: "center" }}>Loading...</div>;
  }

  const pending = users.filter((u) => u.memberId == null);
  const approved = users.filter((u) => u.memberId != null);

  return (
    <div className="adminPage">
      <Navbar />
      <main className="adminWrap">
        <h1 className="adminTitle">멤버 권한 관리</h1>

        {/* 중복 제거 */}
        <section className="adminSection">
          <div className="adminSectionHeader">
            <h2 className="adminSectionTitle">Firebase 중복 제거</h2>
          </div>
          <button
            className="adminApproveBtn"
            onClick={deduplicatePlans}
            disabled={deduping}
            style={{ marginTop: 8, background: "#c0392b" }}
          >
            {deduping ? "처리 중…" : "🗑 중복 계획 제거"}
          </button>
          <p style={{ color: "rgba(255,255,255,0.45)", fontSize: 13, marginTop: 8 }}>
            이름+계획번호가 같은 중복 문서를 삭제해요. 최신 것만 남아요.
          </p>
        </section>

        {/* CSV 내보내기 */}
        <section className="adminSection">
          <div className="adminSectionHeader">
            <h2 className="adminSectionTitle">계획 데이터 내보내기</h2>
          </div>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginTop: 8 }}>
            <button
              className="adminApproveBtn"
              onClick={() => exportCSV("done")}
              disabled={exporting}
              style={{ minWidth: 160 }}
            >
              {exporting ? "내보내는 중…" : "✅ 완료된 계획 CSV"}
            </button>
            <button
              className="adminApproveBtn"
              onClick={() => exportCSV(null)}
              disabled={exporting}
              style={{ minWidth: 160, background: "#4a5568" }}
            >
              {exporting ? "내보내는 중…" : "📋 전체 계획 CSV"}
            </button>
          </div>
          <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 8, flexWrap: "wrap" }}>
            <p style={{ color: "rgba(255,255,255,0.45)", fontSize: 13, margin: 0 }}>
              Chrome/Edge: 처음 한 번 파일 위치 선택 → 이후 같은 파일에 덮어써요.
            </p>
            <button
              onClick={resetFileHandle}
              style={{ background: "none", border: "1px solid rgba(255,255,255,0.2)", color: "rgba(255,255,255,0.5)", fontSize: 12, padding: "2px 8px", borderRadius: 4, cursor: "pointer" }}
            >
              파일 위치 초기화
            </button>
          </div>
        </section>

        {/* 승인 대기 */}
        <section className="adminSection">
          <div className="adminSectionHeader">
            <h2 className="adminSectionTitle">승인 대기</h2>
            <span className="adminBadge">{pending.length}</span>
          </div>

          {pending.length === 0 ? (
            <p className="adminEmpty">대기 중인 가입 요청이 없습니다.</p>
          ) : (
            <div className="adminCards">
              {pending.map((u) => (
                <PendingCard
                  key={u.uid}
                  u={u}
                  members={members}
                  saving={saving}
                  onApprove={approve}
                />
              ))}
            </div>
          )}
        </section>

        {/* 승인 완료 */}
        <section className="adminSection">
          <div className="adminSectionHeader">
            <h2 className="adminSectionTitle">승인 완료</h2>
            <span className="adminBadge adminBadgeGreen">{approved.length}</span>
          </div>

          {approved.length === 0 ? (
            <p className="adminEmpty">승인된 멤버가 없습니다.</p>
          ) : (
            <div className="adminApprovedList">
              {approved.map((u) => {
                const member = members.find((m) => String(m.id) === String(u.memberId));
                return (
                  <div key={u.uid} className="adminApprovedRow">
                    <div className="adminApprovedInfo">
                      <span className="adminApprovedName">{member?.name ?? "알 수 없음"}</span>
                      <span className="adminApprovedEmail">{u.email}</span>
                    </div>
                    <div className="adminApprovedActions">
                      <button
                        className={`adminNetworkingBtn${u.networkingEditor ? " active" : ""}`}
                        onClick={() => toggleNetworking(u.uid, !!u.networkingEditor)}
                        disabled={saving === u.uid + "_net"}
                        title="네트워킹 수정 권한"
                      >
                        {saving === u.uid + "_net" ? "..." : u.networkingEditor ? "네트워킹 ✓" : "네트워킹"}
                      </button>
                      <button
                        className="adminRevokeBtn"
                        onClick={() => revoke(u.uid)}
                        disabled={saving === u.uid + "_revoke"}
                      >
                        {saving === u.uid + "_revoke" ? "처리 중..." : "승인 취소"}
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}

function PendingCard({ u, members, saving, onApprove }) {
  const [selectedId, setSelectedId] = useState(u._suggested ?? "");

  const selectedMember = members.find((m) => String(m.id) === String(selectedId));

  return (
    <div className="adminCard">
      <div className="adminCardEmail">{u.email}</div>
      <div className="adminCardDate">가입일: {u.createdAt?.slice(0, 10) ?? "-"}</div>

      {u._suggestedName && (
        <div className="adminCardSuggested">
          이메일 자동 매칭: <strong>{u._suggestedName}</strong>
        </div>
      )}

      <div className="adminCardRow">
        <select
          className="adminSelect"
          value={selectedId}
          onChange={(e) => setSelectedId(e.target.value)}
        >
          <option value="">— 멤버 선택 —</option>
          {members.map((m) => (
            <option key={m.id} value={m.id}>
              {m.name} ({m.role})
            </option>
          ))}
        </select>

        <button
          className="adminApproveBtn"
          disabled={!selectedId || saving === u.uid}
          onClick={() => onApprove(u.uid, selectedId)}
        >
          {saving === u.uid ? "처리 중..." : "✓ 승인"}
        </button>
      </div>

      {selectedMember && (
        <div className="adminCardPreview">
          {selectedMember.name} · {selectedMember.role}
        </div>
      )}
    </div>
  );
}
